import { loadDestinationEvidence } from "@/lib/data/evidence-v12";
import type { DestinationEvidenceBundle } from "@/lib/decision/types";
import type { V8Ranked } from "@/lib/decision/v8-matcher";
import type { TripRequest } from "@/lib/validation/trip";

export type ResearchNeed = "ancient_history" | "dated_events";
export type ResearchIntent = { needs: Set<ResearchNeed>; explicit: boolean };

const norm = (value: string) => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

export function researchIntent(request: TripRequest): ResearchIntent {
  const text = norm(request.tripText ?? "");
  const needs = new Set<ResearchNeed>();
  if (/αρχαι|αρχαιολογ|μνημει|ιστορικ.{0,12}(χωρ|τοπ)|ancient|archaeolog|historic site/.test(text)) needs.add("ancient_history");
  if (/εκδηλω|φεστιβαλ|συναυλι|παραστασ|event|festival|concert/.test(text)) needs.add("dated_events");
  return { needs, explicit: needs.size > 0 };
}

function textOf(bundle: DestinationEvidenceBundle) {
  return bundle.places.map(item => `${item.subjectName} ${item.headline} ${item.summary ?? ""}`).join(" ");
}

export function satisfiesResearchNeed(bundle: DestinationEvidenceBundle, need: ResearchNeed) {
  if (need === "dated_events") return bundle.hasDateMatchedEvents;
  return /αρχαι|αρχαιολογ|μνημει|ancient|archaeolog|monument|heritage/i.test(norm(textOf(bundle)));
}

export type ResearchScreen = {
  intent: ResearchIntent;
  evidence: Map<string, DestinationEvidenceBundle>;
  verifiedCoverage: Record<ResearchNeed, number>;
  ranked: V8Ranked[];
};

export async function screenResearchEvidence(request: TripRequest, ranked: V8Ranked[], limit = 18): Promise<ResearchScreen> {
  const intent = researchIntent(request);
  const evidence = new Map<string, DestinationEvidenceBundle>();
  const coverage: Record<ResearchNeed, number> = { ancient_history: 0, dated_events: 0 };
  if (!intent.explicit) return { intent, evidence, verifiedCoverage: coverage, ranked };
  const candidates = ranked.slice(0, limit);
  const bundles = await Promise.all(candidates.map(item => loadDestinationEvidence(item.destination.slug, request.startDate, request.endDate)));
  candidates.forEach((item, index) => evidence.set(item.destination.slug, bundles[index]));
  for (const need of intent.needs) coverage[need] = bundles.filter(bundle => satisfiesResearchNeed(bundle, need)).length;
  const rescored = ranked.map(item => {
    const bundle = evidence.get(item.destination.slug);
    if (!bundle) return item;
    let delta = 0;
    for (const need of intent.needs) delta += satisfiesResearchNeed(bundle, need) ? 14 : -10;
    return { ...item, score: Math.max(0, Math.min(100, item.score + delta)) };
  });
  return { intent, evidence, verifiedCoverage: coverage, ranked: rescored.sort((a, b) => b.score - a.score) };
}

import { V8_DIMENSIONS,type V8Dimension,type V8IntentProfile } from "@/lib/decision/v8-types";
import type { V8Ranked } from "@/lib/decision/v8-matcher";

const clamp=(v:number,min:number,max:number)=>Math.max(min,Math.min(max,v));
const index=Object.fromEntries(V8_DIMENSIONS.map((d,i)=>[d,i])) as Record<V8Dimension,number>;

export function semanticAdjustmentV18(item:V8Ranked,intent:V8IntentProfile){
 const semantic=intent.semantic;if(!semantic)return 0;let adjustment=0;
 for(const d of V8_DIMENSIONS){const negative=Math.max(0,Math.min(1,semantic.negative[d]??0));if(!negative)continue;const affinity=Math.max(0,Math.min(1,item.destination.vector[index[d]]??0));adjustment-=negative*affinity*16;if(negative>=.9&&affinity>=.85)adjustment-=5;}
 const q=semantic.qualifiers;if(q.avoidCrowds>0){const crowd=item.destination.crowdLevel;adjustment+=q.avoidCrowds*(crowd<=2?5:crowd===3?1:crowd===4?-5:-10);}
 if(q.easyAccess>0)adjustment+=q.easyAccess*clamp((item.breakdown.effort-72)/5,-8,6);
 if(q.slowRhythm>0){if(item.destination.tags.includes("relax"))adjustment+=3*q.slowRhythm;if(item.destination.tags.includes("nightlife"))adjustment-=4*q.slowRhythm;}
 // Walkability and local character are not asserted as destination facts here. Their positive influence is already represented conservatively through city/culture weights in the canonical intent contract.
 return clamp(adjustment,-24,12);
}

export function applySemanticIntentRankingV18(items:V8Ranked[],intent:V8IntentProfile){
 if(!intent.semantic)return items;return items.map(item=>{const adjustment=semanticAdjustmentV18(item,intent);return{...item,score:clamp(item.score+adjustment,0,100),preScore:clamp(item.preScore+adjustment,0,100)}}).sort((a,b)=>b.score-a.score);
}

import { loadV8StayOffers } from "@/lib/data/destination-v8";
import type { V8Recommendation, V8RecommendationResponse, V8StayOffer } from "@/lib/decision/v8-types";
import type { TripRequest } from "@/lib/validation/trip";

export interface RankedStayV35 {
  sourceProductId: string;
  propertyName: string;
  trackingUrl: string;
  imageUrl: string | null;
  price: number | null;
  fullPrice: number | null;
  currency: string | null;
  discountPct: number | null;
  availability: string | null;
  inStock: boolean | null;
  city: string | null;
  address: string | null;
  distanceKm: number | null;
  score: number;
  reasons: string[];
  tradeoff: string;
}

export interface EscapeSolutionV35 {
  rank: number;
  originalRank: number;
  combinedScore: number;
  destinationScore: number;
  inventoryScore: number;
  inventoryDepth: number;
  recommendation: V8Recommendation;
  stay: RankedStayV35;
  alternatives: RankedStayV35[];
  reasoning: {
    destination: string;
    stay: string;
    reverse: string;
    tradeoff: string;
  };
}

export interface EscapeSolutionResponseV35 {
  version: 35;
  generatedAt: string;
  request: TripRequest;
  profileSummary: string;
  candidateCount: number;
  inventoryChecked: number;
  solutionCount: number;
  solutions: EscapeSolutionV35[];
}

const clamp=(value:number,min=0,max=100)=>Math.max(min,Math.min(max,value));
const lang=(request:TripRequest)=>request.language==="en"?"en":"el";
const say=(request:TripRequest,el:string,en:string)=>lang(request)==="en"?en:el;
const parseDate=(value:string|null|undefined)=>value?Date.parse(`${value.slice(0,10)}T00:00:00Z`):NaN;

function discountPct(offer:V8StayOffer):number|null{
  if(offer.fullPrice!=null&&offer.price!=null&&offer.fullPrice>offer.price&&offer.fullPrice>0){
    return clamp(((offer.fullPrice-offer.price)/offer.fullPrice)*100,0,90);
  }
  if(offer.discount!=null&&Number.isFinite(offer.discount)){
    const raw=Number(offer.discount);
    return raw>0&&raw<=100?raw:null;
  }
  return null;
}

function validForWindow(offer:V8StayOffer,request:TripRequest){
  const start=Date.parse(`${request.startDate}T00:00:00Z`),end=Date.parse(`${request.endDate}T00:00:00Z`);
  const from=parseDate(offer.validFrom),to=parseDate(offer.validTo);
  if(Number.isFinite(from)&&from>start)return false;
  if(Number.isFinite(to)&&to<end)return false;
  return true;
}

function availabilitySignal(value:string|null|undefined){
  const text=(value??"").toLowerCase();
  if(/unavailable|sold out|not available|εξαντ|μη διαθέσι/.test(text))return -20;
  if(/available|in stock|διαθέσι/.test(text))return 8;
  return 3;
}

function scoreStay(offer:V8StayOffer,request:TripRequest):RankedStayV35|null{
  if(offer.inStock===false||!validForWindow(offer,request))return null;
  let score=0;
  const reasons:string[]=[];
  score+=offer.inStock===true?22:12;
  if(offer.inStock===true)reasons.push(say(request,"Δηλώνεται ενεργό στο feed","Marked active in the feed"));

  const availability=availabilitySignal(offer.availability);
  if(availability<0)return null;
  score+=availability;

  if(offer.price!=null&&offer.price>0){
    const ratio=offer.price/Math.max(1,request.budget);
    score+=ratio<=0.6?18:ratio<=0.9?15:ratio<=1.1?11:ratio<=1.35?6:2;
    reasons.push(say(request,`Τιμή feed ${offer.currency??"€"} ${Math.round(offer.price)}`,`Feed price ${offer.currency??"€"} ${Math.round(offer.price)}`));
  }else score+=7;

  const pct=discountPct(offer);
  if(pct!=null){score+=Math.min(10,pct/5);if(pct>=10)reasons.push(say(request,`Έκπτωση περίπου ${Math.round(pct)}% στο feed`,`About ${Math.round(pct)}% feed discount`));}

  if(offer.distanceKm!=null){
    score+=offer.distanceKm<=2?13:offer.distanceKm<=6?10:offer.distanceKm<=15?7:offer.distanceKm<=30?3:0;
    if(offer.distanceKm<=6)reasons.push(say(request,"Καλή εγγύτητα στον προορισμό","Good destination proximity"));
  }else score+=5;

  if(offer.demandSignal!=null&&offer.demandSignal>0)score+=Math.min(8,Math.log10(1+offer.demandSignal)*2.4);
  if(offer.imageUrl||offer.thumbUrl)score+=4;
  if(offer.propertyName)score+=3;

  let tradeoff=say(request,"Η τελική τιμή και το δωμάτιο επιβεβαιώνονται στον πάροχο.","Final price and room details must be confirmed with the provider.");
  if(offer.inStock==null)tradeoff=say(request,"Το feed δεν δίνει βέβαιη κατάσταση stock· χρειάζεται επιβεβαίωση στον πάροχο.","The feed does not provide confirmed stock; provider confirmation is required.");
  else if(offer.distanceKm!=null&&offer.distanceKm>20)tradeoff=say(request,"Είναι πιο μακριά από τον πυρήνα του προορισμού, άρα θέλει έλεγχο μετακίνησης.","It sits farther from the destination core, so transport friction needs checking.");

  return{
    sourceProductId:offer.sourceProductId,
    propertyName:offer.propertyName,
    trackingUrl:offer.trackingUrl,
    imageUrl:offer.imageUrl??offer.thumbUrl??null,
    price:offer.price??null,
    fullPrice:offer.fullPrice??null,
    currency:offer.currency??null,
    discountPct:pct,
    availability:offer.availability??null,
    inStock:offer.inStock??null,
    city:offer.city??null,
    address:offer.address??null,
    distanceKm:offer.distanceKm??null,
    score:Math.round(clamp(score)),
    reasons:reasons.slice(0,4),
    tradeoff,
  };
}

async function inventoryFor(rec:V8Recommendation,request:TripRequest){
  try{
    const offers=await loadV8StayOffers(rec.slug,request.startDate,request.endDate,36);
    const ranked=offers.map(offer=>scoreStay(offer,request)).filter((offer):offer is RankedStayV35=>Boolean(offer)).sort((a,b)=>b.score-a.score||(a.price??Number.MAX_SAFE_INTEGER)-(b.price??Number.MAX_SAFE_INTEGER));
    return{rec,ranked};
  }catch{return{rec,ranked:[] as RankedStayV35[]};}
}

export async function buildEscapeSolutionsV35(request:TripRequest,base:V8RecommendationResponse,maxSolutions=10):Promise<EscapeSolutionResponseV35>{
  const candidates=base.recommendations.slice(0,18);
  const rows:Array<{rec:V8Recommendation;ranked:RankedStayV35[]}>=[];
  for(let offset=0;offset<candidates.length;offset+=4){
    rows.push(...await Promise.all(candidates.slice(offset,offset+4).map(rec=>inventoryFor(rec,request))));
  }

  const provisional=rows.flatMap((row,index)=>{
    const best=row.ranked[0];
    if(!best)return[];
    const inventoryDepth=Math.round(clamp((Math.min(row.ranked.length,10)/10)*100));
    const inventoryScore=Math.round(clamp(best.score*0.78+inventoryDepth*0.22));
    const combinedScore=Math.round(clamp(row.rec.score*0.72+inventoryScore*0.28));
    return[{originalRank:index+1,combinedScore,destinationScore:Math.round(row.rec.score),inventoryScore,inventoryDepth,recommendation:row.rec,stay:best,alternatives:row.ranked.slice(1,4)}];
  }).sort((a,b)=>b.combinedScore-a.combinedScore||b.destinationScore-a.destinationScore).slice(0,Math.max(1,Math.min(10,maxSolutions)));

  const solutions:EscapeSolutionV35[]=provisional.map((item,index)=>{
    const rank=index+1,delta=item.originalRank-rank;
    const reverse=delta>0
      ?say(request,`Ανέβηκε ${delta} θέση${delta===1?"":"εις"} επειδή το πραγματικό inventory είναι ισχυρότερο από άλλες θεωρητικά καλές επιλογές.`,`Moved up ${delta} place${delta===1?"":"s"} because the real stay inventory is stronger than other theoretically good matches.`)
      :delta<0
       ?say(request,`Έπεσε ${Math.abs(delta)} θέση${Math.abs(delta)===1?"":"εις"}: το destination fit είναι καλό, αλλά το διαθέσιμο inventory είναι λιγότερο πειστικό.`,`Moved down ${Math.abs(delta)} place${Math.abs(delta)===1?"":"s"}: destination fit is good, but the available inventory is less convincing.`)
       :say(request,"Κράτησε τη θέση του: destination fit και πραγματικό inventory συμφωνούν.","Held its position: destination fit and real inventory agree.");
    const stayWhy=item.stay.reasons.length?item.stay.reasons.join(" · "):say(request,"Είναι η ισχυρότερη πραγματική επιλογή διαμονής που βρήκα για αυτό το ταξίδι.","It is the strongest real stay option found for this trip.");
    return{...item,rank,reasoning:{destination:item.recommendation.why,stay:stayWhy,reverse,tradeoff:item.stay.tradeoff}};
  });

  return{
    version:35,
    generatedAt:new Date().toISOString(),
    request,
    profileSummary:base.profileSummary,
    candidateCount:candidates.length,
    inventoryChecked:rows.length,
    solutionCount:solutions.length,
    solutions,
  };
}

import { interpretIntentV8 } from "@/lib/ai/intent-v8";
import { createLLMRequestBudgetV16 } from "@/lib/ai/model-router-v9";
import { loadV8DestinationCatalog, loadV8StayOffers } from "@/lib/data/destination-v8";
import { preRankV8, toRecommendationsV8 } from "@/lib/decision/v8-matcher";
import type { V8IntentProfile, V8Recommendation, V8RecommendationResponse, V8StayOffer } from "@/lib/decision/v8-types";
import type { TripRequest } from "@/lib/validation/trip";

export interface RankedStayV36 {
  sourceProductId:string;
  propertyName:string;
  trackingUrl:string;
  imageUrl:string|null;
  price:number|null;
  fullPrice:number|null;
  currency:string|null;
  discountPct:number|null;
  availability:string|null;
  inStock:boolean|null;
  city:string|null;
  address:string|null;
  distanceKm:number|null;
  score:number;
  semanticScore:number;
  valueScore:number;
  locationScore:number;
  evidenceScore:number;
  reasons:string[];
  matchedSignals:string[];
  tradeoff:string;
}

export interface EscapeSolutionV36 {
  rank:number;
  forwardRank:number;
  combinedScore:number;
  destinationScore:number;
  stayScore:number;
  inventoryDepth:number;
  inventoryCount:number;
  recommendation:V8Recommendation;
  stay:RankedStayV36;
  alternatives:RankedStayV36[];
  reasoning:{
    destination:string;
    stay:string;
    reverse:string;
    tradeoff:string;
  };
}

export interface EscapeSolutionResponseV36 {
  version:36;
  generatedAt:string;
  request:TripRequest;
  profileSummary:string;
  candidateCount:number;
  inventoryChecked:number;
  inventoryOfferCount:number;
  inventoryLookupSuccesses:number;
  inventoryLookupFailures:number;
  solutionCount:number;
  sourceMode:"forward+reverse"|"reverse-recovery"|"constraint-relaxation";
  solutions:EscapeSolutionV36[];
}

const clamp=(v:number,min=0,max=100)=>Math.max(min,Math.min(max,v));
const say=(request:TripRequest,el:string,en:string)=>request.language==="en"?en:el;
const parseDate=(value:string|null|undefined)=>value?Date.parse(`${value.slice(0,10)}T00:00:00Z`):NaN;

function discountPct(offer:V8StayOffer):number|null{
  if(offer.fullPrice!=null&&offer.price!=null&&offer.fullPrice>offer.price&&offer.fullPrice>0)return clamp(((offer.fullPrice-offer.price)/offer.fullPrice)*100,0,90);
  if(offer.discount!=null&&Number.isFinite(offer.discount)){const n=Number(offer.discount);return n>0&&n<=100?n:null;}
  return null;
}

function validForWindow(offer:V8StayOffer,request:TripRequest){
  const start=Date.parse(`${request.startDate}T00:00:00Z`),end=Date.parse(`${request.endDate}T00:00:00Z`),from=parseDate(offer.validFrom),to=parseDate(offer.validTo);
  if(Number.isFinite(from)&&from>start)return false;
  if(Number.isFinite(to)&&to<end)return false;
  return true;
}

function haystack(offer:V8StayOffer){
  const raw=offer.raw&&typeof offer.raw==="object"?JSON.stringify(offer.raw):"";
  return `${offer.propertyName} ${offer.description??""} ${offer.category??""} ${raw}`.toLowerCase();
}

const signalPatterns:{id:string;pattern:RegExp;el:string;en:string}[]=[
  {id:"sea",pattern:/beach|beachfront|seaside|sea view|coast|παραλ|θάλασσ|θαλασσ/,el:"θάλασσα / παραλία",en:"sea / beach"},
  {id:"nature",pattern:/garden|forest|mountain|nature|eco|rural|vineyard|κήπ|βουν|φύσ|φυση/,el:"φύση",en:"nature"},
  {id:"wellness",pattern:/spa|wellness|massage|thermal|sauna|hamam|hammam|ευεξ/,el:"wellness / spa",en:"wellness / spa"},
  {id:"romantic",pattern:/boutique|suite|adults only|romantic|honeymoon|private|μπουτίκ|σουίτα/,el:"boutique / romantic χαρακτήρα",en:"boutique / romantic character"},
  {id:"family",pattern:/family|kids|children|apartment|kitchen|family room|παιδ|οικογεν|διαμέρισμα|διαμερισμα/,el:"family-friendly στοιχεία",en:"family-friendly cues"},
  {id:"city",pattern:/old town|historic|centre|center|downtown|city centre|κέντρο|κεντρο|παλιά πόλη|παλια πολη/,el:"κεντρική / city βάση",en:"central / city base"},
  {id:"pool",pattern:/pool|swimming|πισίνα|πισινα/,el:"πισίνα",en:"pool"},
  {id:"luxury",pattern:/luxury|5 star|5\*|resort|premium|deluxe|πολυτελ/,el:"premium χαρακτήρα",en:"premium character"}
];

function desiredSignals(request:TripRequest){
  const wanted=new Set<string>();
  for(const mood of request.moods){
    if(mood==="romantic")wanted.add("romantic");
    if(mood==="nature")wanted.add("nature");
    if(mood==="city"||mood==="culture"||mood==="food")wanted.add("city");
    if(mood==="relax")wanted.add("wellness");
    if(mood==="warmth")wanted.add("sea");
  }
  if(request.mustHave==="sea")wanted.add("sea");
  if(request.mustHave==="nature")wanted.add("nature");
  if(request.mustHave==="culture"||request.mustHave==="nightlife")wanted.add("city");
  if(request.travelerType==="family")wanted.add("family");
  if(request.hotelStyle==="luxury")wanted.add("luxury");
  if(request.hotelStyle==="boutique")wanted.add("romantic");
  if(request.hotelStyle==="resort")wanted.add("pool");
  return wanted;
}

function scoreStay(offer:V8StayOffer,request:TripRequest):RankedStayV36|null{
  if(offer.inStock===false||!validForWindow(offer,request))return null;
  const text=haystack(offer),wanted=desiredSignals(request),matched=signalPatterns.filter(item=>wanted.has(item.id)&&item.pattern.test(text));
  const semanticScore=clamp(42+matched.length*14+(request.travelerType==="couple"&&/adults only|boutique|suite|private/.test(text)?8:0)+(request.travelerType==="family"&&/family|kids|apartment|kitchen/.test(text)?10:0));
  const pct=discountPct(offer);
  let valueScore=50;
  if(offer.price!=null&&offer.price>0){const ratio=offer.price/Math.max(1,request.budget);valueScore=ratio<=.45?90:ratio<=.7?82:ratio<=.95?72:ratio<=1.15?58:ratio<=1.4?42:28;}
  if(pct!=null)valueScore=clamp(valueScore+Math.min(12,pct*.35));
  const locationScore=offer.distanceKm==null?55:offer.distanceKm<=2?94:offer.distanceKm<=6?84:offer.distanceKm<=15?68:offer.distanceKm<=30?48:30;
  const evidenceScore=clamp((offer.inStock===true?30:16)+(offer.availability?14:6)+(offer.imageUrl||offer.thumbUrl?12:4)+(offer.description?18:7)+(offer.address||offer.city?12:5)+(offer.distanceKm!=null?14:5));
  const score=Math.round(clamp(semanticScore*.34+valueScore*.24+locationScore*.20+evidenceScore*.22));
  const reasons:string[]=[];
  if(matched.length)reasons.push(say(request,`Το feed αναφέρει στοιχεία που ταιριάζουν σε: ${matched.slice(0,3).map(x=>x.el).join(", ")}.`,`The feed mentions cues matching: ${matched.slice(0,3).map(x=>x.en).join(", ")}.`));
  if(offer.distanceKm!=null&&offer.distanceKm<=10)reasons.push(say(request,`Βρίσκεται περίπου ${offer.distanceKm.toFixed(1)} km από τον πυρήνα του προορισμού.`,`It is about ${offer.distanceKm.toFixed(1)} km from the destination core.`));
  if(offer.inStock===true)reasons.push(say(request,"Το feed το δηλώνει ενεργό για αναζήτηση.","The feed marks it active for search."));
  if(offer.price!=null)reasons.push(say(request,`Η τιμή feed είναι ${offer.currency??"EUR"} ${Math.round(offer.price)} και χρησιμοποιείται μόνο ως σήμα αξίας, όχι ως τελική τιμή κράτησης.`,`The feed price is ${offer.currency??"EUR"} ${Math.round(offer.price)} and is used only as a value signal, not a final booking price.`));
  if(pct!=null&&pct>=10)reasons.push(say(request,`Το feed δείχνει περίπου ${Math.round(pct)}% διαφορά από την πλήρη τιμή.`,`The feed shows about ${Math.round(pct)}% difference from full price.`));
  let tradeoff=say(request,"Η τελική τιμή, ο τύπος δωματίου και η πραγματική διαθεσιμότητα επιβεβαιώνονται πάντα στον πάροχο.","Final price, room type and live availability must always be confirmed with the provider.");
  if(!matched.length)tradeoff=say(request,"Το inventory είναι λειτουργικό, αλλά το feed δεν τεκμηριώνει αρκετά mood-specific χαρακτηριστικά· γι’ αυτό δεν παίρνει υψηλό semantic score.","The inventory is usable, but the feed does not document enough mood-specific features, so it does not receive a high semantic score.");
  if(offer.distanceKm!=null&&offer.distanceKm>20)tradeoff=say(request,"Το κατάλυμα είναι αρκετά έξω από τον πυρήνα του προορισμού· η μετακίνηση είναι πραγματικό trade-off.","The stay is well outside the destination core; transport is a real trade-off.");
  return{sourceProductId:offer.sourceProductId,propertyName:offer.propertyName,trackingUrl:offer.trackingUrl,imageUrl:offer.imageUrl??offer.thumbUrl??null,price:offer.price??null,fullPrice:offer.fullPrice??null,currency:offer.currency??null,discountPct:pct,availability:offer.availability??null,inStock:offer.inStock??null,city:offer.city??null,address:offer.address??null,distanceKm:offer.distanceKm??null,score,semanticScore:Math.round(semanticScore),valueScore:Math.round(valueScore),locationScore:Math.round(locationScore),evidenceScore:Math.round(evidenceScore),reasons:reasons.slice(0,4),matchedSignals:matched.map(item=>request.language==="en"?item.en:item.el).slice(0,5),tradeoff};
}

async function resolveIntent(request:TripRequest,base:V8RecommendationResponse|null):Promise<V8IntentProfile>{
  if(base?.intent)return base.intent;
  return interpretIntentV8(request,createLLMRequestBudgetV16());
}

function candidatePool(base:V8RecommendationResponse|null,global:V8Recommendation[]){
  const map=new Map<string,V8Recommendation>();
  for(const rec of base?.recommendations??[])map.set(rec.slug,rec);
  for(const rec of global)if(!map.has(rec.slug))map.set(rec.slug,rec);
  return[...map.values()];
}

type InventoryRow={rec:V8Recommendation;ranked:RankedStayV36[];error?:string};

async function inventoryFor(rec:V8Recommendation,request:TripRequest):Promise<InventoryRow>{
  try{
    const offers=await loadV8StayOffers(rec.slug,request.startDate,request.endDate,60);
    const ranked=offers.map(x=>scoreStay(x,request)).filter((x):x is RankedStayV36=>Boolean(x)).sort((a,b)=>b.score-a.score||(a.price??Number.MAX_SAFE_INTEGER)-(b.price??Number.MAX_SAFE_INTEGER));
    return{rec,ranked};
  }catch(error){return{rec,ranked:[],error:error instanceof Error?error.message:"inventory_lookup_failed"};}
}

async function scanAll(candidates:V8Recommendation[],request:TripRequest){
  const rows:InventoryRow[]=[];
  for(let offset=0;offset<candidates.length;offset+=5)rows.push(...await Promise.all(candidates.slice(offset,offset+5).map(rec=>inventoryFor(rec,request))));
  return rows;
}

function buildSolutions(request:TripRequest,candidates:V8Recommendation[],rows:InventoryRow[],maxSolutions:number){
  const forwardRank=new Map(candidates.map((rec,index)=>[rec.slug,index+1]));
  const provisional=rows.flatMap(row=>{
    const best=row.ranked[0];if(!best)return[];
    const inventoryCount=row.ranked.length,inventoryDepth=Math.round(clamp((Math.min(inventoryCount,20)/20)*100));
    const stayScore=Math.round(clamp(best.score*.76+inventoryDepth*.24));
    const combinedScore=Math.round(clamp(row.rec.score*.56+stayScore*.44));
    return[{forwardRank:forwardRank.get(row.rec.slug)??99,combinedScore,destinationScore:Math.round(row.rec.score),stayScore,inventoryDepth,inventoryCount,recommendation:row.rec,stay:best,alternatives:row.ranked.slice(1,10)}];
  }).sort((a,b)=>b.combinedScore-a.combinedScore||b.stayScore-a.stayScore||b.destinationScore-a.destinationScore).slice(0,Math.max(1,Math.min(10,maxSolutions)));

  return provisional.map((item,index):EscapeSolutionV36=>{
    const rank=index+1,delta=item.forwardRank-rank;
    const reverse=delta>0?say(request,`Η διαμονή άλλαξε την απόφαση: ο προορισμός ανέβηκε ${delta} θέση${delta===1?"":"εις"} όταν ελέγξαμε το πραγματικό inventory.`,`The stay inventory changed the decision: this destination moved up ${delta} place${delta===1?"":"s"} after checking real inventory.`):delta<0?say(request,`Ο προορισμός ήταν ισχυρός θεωρητικά, αλλά έπεσε ${Math.abs(delta)} θέση${Math.abs(delta)===1?"":"εις"} επειδή τα πραγματικά καταλύματα είναι πιο αδύναμα από άλλες λύσεις.`,`The destination was strong in theory, but moved down ${Math.abs(delta)} place${Math.abs(delta)===1?"":"s"} because its real stays are weaker than other solutions.`):say(request,"Forward fit και reverse inventory check συμφωνούν — η θέση του προορισμού επιβεβαιώθηκε.","Forward fit and the reverse inventory check agree — the destination kept its position.");
    const stay=item.stay.reasons.length?item.stay.reasons.join(" "):say(request,"Είναι η ισχυρότερη τεκμηριωμένη διαμονή που βρήκα για αυτή τη λύση.","It is the strongest documented stay found for this solution.");
    return{...item,rank,reasoning:{destination:item.recommendation.why,stay,reverse,tradeoff:item.stay.tradeoff}};
  });
}

export async function buildEscapeSolutionsV36(request:TripRequest,base:V8RecommendationResponse|null,maxSolutions=10):Promise<EscapeSolutionResponseV36>{
  const[intent,catalog]=await Promise.all([resolveIntent(request,base),loadV8DestinationCatalog()]);
  const globalRanked=preRankV8(request,intent,catalog,Math.max(1,catalog.length));
  const globalRecommendations=toRecommendationsV8(request,globalRanked);
  let candidates=candidatePool(base,globalRecommendations);
  let rows=await scanAll(candidates,request);
  let sourceMode:EscapeSolutionResponseV36["sourceMode"]=base?"forward+reverse":"reverse-recovery";

  let successes=rows.filter(row=>!row.error).length;
  let failures=rows.filter(row=>Boolean(row.error)).length;
  if(successes===0&&failures>0)throw new Error(`Stay inventory backend failed for all ${failures} destination lookups`);

  let solutions=buildSolutions(request,candidates,rows,maxSolutions);
  if(!solutions.length){
    const relaxedRequest:TripRequest={...request,mustHave:"none",distancePreference:"any",avoid:"none"};
    const relaxedRanked=preRankV8(relaxedRequest,intent,catalog,Math.max(1,catalog.length));
    const relaxedRecommendations=toRecommendationsV8(relaxedRequest,relaxedRanked).map(rec=>({...rec,fitStatus:"compromise" as const,why:say(request,`Κοντινή εναλλακτική όταν χαλαρώνουμε μόνο τα σκληρά φίλτρα: ${rec.why}`,`Closest alternative after relaxing only the hard filters: ${rec.why}`)}));
    candidates=candidatePool(null,relaxedRecommendations);
    rows=await scanAll(candidates,request);
    sourceMode="constraint-relaxation";
    successes=rows.filter(row=>!row.error).length;
    failures=rows.filter(row=>Boolean(row.error)).length;
    if(successes===0&&failures>0)throw new Error(`Stay inventory backend failed for all ${failures} relaxed destination lookups`);
    solutions=buildSolutions(request,candidates,rows,maxSolutions);
  }

  return{version:36,generatedAt:new Date().toISOString(),request,profileSummary:base?.profileSummary??intent.summary,candidateCount:candidates.length,inventoryChecked:rows.length,inventoryOfferCount:rows.reduce((sum,row)=>sum+row.ranked.length,0),inventoryLookupSuccesses:successes,inventoryLookupFailures:failures,solutionCount:solutions.length,sourceMode,solutions};
}

import type { V8StayOffer } from "@/lib/decision/v8-types";

export type StayAvailabilityTruthV20 =
  | "CONFIRMED_ACTIVE"
  | "VALID_WINDOW_STOCK_UNKNOWN"
  | "EXPLICITLY_UNAVAILABLE"
  | "OUTSIDE_VALIDITY_WINDOW"
  | "INVALID_FEED_EVIDENCE";

export interface StayAvailabilityAssessmentV20 {
  truth: StayAvailabilityTruthV20;
  confidence: "HIGH" | "MEDIUM" | "LOW";
  fullTripWindowCovered: boolean;
  stockState: "AVAILABLE" | "UNAVAILABLE" | "UNKNOWN";
  providerConfirmationRequired: true;
  reason: string;
}

const linkwiseTracking = (url: string) =>
  url.startsWith("https://go.linkwi.se/") && url.includes("/CD104/");

export function assessStayAvailabilityV20(
  offer: V8StayOffer,
  startDate: string,
  endDate: string,
): StayAvailabilityAssessmentV20 {
  const start = Date.parse(`${startDate}T00:00:00Z`);
  const end = Date.parse(`${endDate}T00:00:00Z`);
  const validFrom = offer.validFrom ? Date.parse(offer.validFrom) : Number.NaN;
  const validTo = offer.validTo ? Date.parse(offer.validTo) : Number.NaN;
  const validDates = Number.isFinite(start) && Number.isFinite(end) && end > start;
  const feedDates = Number.isFinite(validFrom) && Number.isFinite(validTo);
  const fullTripWindowCovered = validDates && feedDates && validFrom <= start && validTo >= end;

  if (!linkwiseTracking(offer.trackingUrl) || !feedDates) {
    return {
      truth: "INVALID_FEED_EVIDENCE",
      confidence: "LOW",
      fullTripWindowCovered: false,
      stockState: offer.inStock === true ? "AVAILABLE" : offer.inStock === false ? "UNAVAILABLE" : "UNKNOWN",
      providerConfirmationRequired: true,
      reason: "Tracking or dated feed evidence is incomplete.",
    };
  }

  if (!fullTripWindowCovered) {
    return {
      truth: "OUTSIDE_VALIDITY_WINDOW",
      confidence: "HIGH",
      fullTripWindowCovered: false,
      stockState: offer.inStock === true ? "AVAILABLE" : offer.inStock === false ? "UNAVAILABLE" : "UNKNOWN",
      providerConfirmationRequired: true,
      reason: "The feed validity window does not cover the full requested trip.",
    };
  }

  if (offer.inStock === false) {
    return {
      truth: "EXPLICITLY_UNAVAILABLE",
      confidence: "HIGH",
      fullTripWindowCovered: true,
      stockState: "UNAVAILABLE",
      providerConfirmationRequired: true,
      reason: "The feed explicitly marks the offer unavailable.",
    };
  }

  if (offer.inStock === true) {
    return {
      truth: "CONFIRMED_ACTIVE",
      confidence: "HIGH",
      fullTripWindowCovered: true,
      stockState: "AVAILABLE",
      providerConfirmationRequired: true,
      reason: "The feed explicitly marks the offer active and its validity covers the full trip.",
    };
  }

  return {
    truth: "VALID_WINDOW_STOCK_UNKNOWN",
    confidence: "MEDIUM",
    fullTripWindowCovered: true,
    stockState: "UNKNOWN",
    providerConfirmationRequired: true,
    reason: "The feed validity covers the trip, but stock state is not explicitly supplied.",
  };
}

import type { StayConstraintKind, StayConstraintSpec, V8StayOffer } from "@/lib/decision/v8-types";

const norm=(value:string)=>value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/\s+/g," ").trim();
const cleanHtml=(value:string)=>value.replace(/<[^>]*>/g," ").replace(/&[a-z]+;/gi," ").replace(/\s+/g," ").trim();
const unique=<T,>(values:T[])=>[...new Set(values)];
export const STAY_CONSTRAINT_KINDS_V16:StayConstraintKind[]=["BEACHFRONT","NEAR_BEACH","SEA_VIEW","POOL","PARKING","EV_CHARGING","BREAKFAST","PET_FRIENDLY","FAMILY_ROOM","ADULTS_ONLY"];
export const STAY_EXCLUSIVE_V16=/(?:μονο|αποκλειστικ|οπωσδηποτε|\bmust\b|\bonly\b|\bstrictly\b|\bmono\b|\bapokleistik)/i;
export const STAY_NOUN_V16=/(?:καταλυμ|ξενοδοχει|δωματι|διαμον|hotel|stay|room|katalym|xenodox|diamoni)/i;

const patterns:Record<StayConstraintKind,RegExp[]>={
 BEACHFRONT:[/beachfront/i,/sea[ -]?front/i,/on the beach/i,/directly on the beach/i,/μπροστα.{0,30}(?:θαλασσ|παραλι)/i,/πανω.{0,30}(?:θαλασσ|παραλι)/i,/ακριβως.{0,30}παραλι/i,/παραθαλασσι(?:ο|α|ες)/i,/mprosta.{0,30}(?:thalass|parali)/i,/pano.{0,30}(?:thalass|parali)/i,/parathalassi/i],
 NEAR_BEACH:[/διπλα.{0,30}(?:θαλασσ|παραλι)/i,/κοντα.{0,30}παραλι/i,/walking distance.{0,30}(?:beach|sea)/i,/near (?:the )?beach/i,/close to (?:the )?beach/i,/dipla.{0,30}(?:thalass|parali)/i,/konta.{0,30}parali/i],
 SEA_VIEW:[/sea view/i,/ocean view/i,/θεα.{0,20}θαλασσ/i,/θαλασσ.{0,20}θεα/i,/thea.{0,20}thalass/i],
 POOL:[/\bpool\b/i,/πισιν/i,/pisin/i],PARKING:[/\bparking\b/i,/παρκιν/i],
 EV_CHARGING:[/(?:ev|electric).{0,20}(?:charg|φορτι)/i,/φορτιστ.{0,20}(?:ηλεκτρ|ev)/i,/fortist.{0,20}(?:ilektr|ev)/i],
 BREAKFAST:[/breakfast/i,/πρωιν/i,/proin/i],PET_FRIENDLY:[/pet[ -]?friendly/i,/κατοικιδ/i,/pet allowed/i,/katoikid/i],
 FAMILY_ROOM:[/family room/i,/family rooms/i,/οικογενειακ.{0,20}δωματι/i,/oikogeneiak.{0,20}domati/i],ADULTS_ONLY:[/adults?[ -]?only/i,/μονο.{0,15}ενηλικ/i,/mono.{0,15}enilik/i],
