function mentions(kind:StayConstraintKind,text:string){return patterns[kind].some(pattern=>pattern.test(text));}
function hasScopedExclusivity(text:string,kind:StayConstraintKind){const n=norm(text),terms:Record<StayConstraintKind,string[]>={BEACHFRONT:["beachfront","sea front","θαλασσ","παραλι","thalass","parali"],NEAR_BEACH:["παραλι","θαλασσ","beach","parali","thalass"],SEA_VIEW:["sea view","θεα","thea"],POOL:["pool","πισιν","pisin"],PARKING:["parking","παρκιν"],EV_CHARGING:["φορτι","charg","forti"],BREAKFAST:["breakfast","πρωιν","proin"],PET_FRIENDLY:["pet","κατοικιδ","katoikid"],FAMILY_ROOM:["family room","οικογενειακ","oikogeneiak"],ADULTS_ONLY:["adults only","ενηλικ","enilik"]},clauses=n.split(/\s+(?:και|and|αλλα|but)\s+|[,;]/).map(value=>value.trim()).filter(Boolean);return clauses.some(clause=>STAY_EXCLUSIVE_V16.test(clause)&&terms[kind].some(term=>clause.includes(term)));}
export function parseStayConstraintsV16(raw:string|undefined|null):StayConstraintSpec{const text=norm(raw??"");if(!text)return{hard:[],soft:[],confidence:"HIGH",source:"deterministic",needsSemanticAssist:false};const hard:StayConstraintKind[]=[],soft:StayConstraintKind[]=[];for(const kind of STAY_CONSTRAINT_KINDS_V16){if(!mentions(kind,text))continue;if(hasScopedExclusivity(text,kind))hard.push(kind);else soft.push(kind);}if(mentions("BEACHFRONT",text)&&!hard.includes("BEACHFRONT")&&!soft.includes("BEACHFRONT"))soft.push("BEACHFRONT");const ambiguousStayLanguage=STAY_NOUN_V16.test(text)&&/(θελω|want|χρειαζ|prepei|πρεπει|na einai|να ειναι)/i.test(text)&&hard.length===0&&soft.length===0,multipleClauses=(text.match(/(?:,| και | αλλα | χωρις | με | but | and | without )/g)??[]).length>=3;return{hard:unique(hard),soft:unique(soft.filter(kind=>!hard.includes(kind))),confidence:(ambiguousStayLanguage||multipleClauses)?"MEDIUM":"HIGH",source:"deterministic",needsSemanticAssist:ambiguousStayLanguage||multipleClauses};}
function rawText(offer:V8StayOffer){const raw=offer.raw&&typeof offer.raw==="object"?offer.raw:{},fields=[offer.propertyName,offer.description,offer.city,offer.address,typeof raw.details==="string"?raw.details:"",typeof raw.product_name==="string"?raw.product_name:"",typeof raw.extra_title==="string"?raw.extra_title:"",typeof raw.type==="string"?raw.type:""];return norm(cleanHtml(fields.filter(Boolean).join(" ")));}
function explicitBeachDistanceMeters(text:string){const distancePatterns=[/(\d{1,4})\s*(?:m|meters?|metres?|μετρ(?:α|ων)?)\s*(?:(?:from|απο)\s*)?(?:(?:the|την|τη)\s*)?(?:beach|παραλι)/i,/(?:beach|παραλι).{0,25}?(\d{1,4})\s*(?:m|meters?|metres?|μετρ(?:α|ων)?)/i];for(const pattern of distancePatterns){const match=text.match(pattern);if(match){const n=Number(match[1]);if(Number.isFinite(n))return n;}}return null;}
const evidenceNegation:Record<StayConstraintKind,RegExp[]>={
 BEACHFRONT:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,18}(?:beachfront|sea[ -]?front|on the beach|παραθαλασ|παραλι)/i],
 NEAR_BEACH:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,18}(?:near.{0,8}beach|close.{0,8}beach|walking distance.{0,8}beach|κοντα.{0,8}παραλι)/i],
 SEA_VIEW:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,18}(?:sea view|ocean view|θεα.{0,8}θαλασσ)/i],
 POOL:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,12}(?:pool|πισιν)/i],
 PARKING:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,12}(?:parking|παρκιν)/i],
 EV_CHARGING:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,18}(?:(?:ev|electric).{0,8}charg|φορτιστ)/i],
 BREAKFAST:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,12}(?:breakfast|πρωιν|proin)/i,/(?:breakfast|πρωιν).{0,12}(?:not included|unavailable|δεν περιλαμβ)/i],
 PET_FRIENDLY:[/(?:\bno\b|without|χωρις|οχι).{0,12}(?:pets?|κατοικιδ)/i,/(?:pets?|κατοικιδ).{0,15}(?:not allowed|δεν επιτρεπ)/i],
 FAMILY_ROOM:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,15}(?:family rooms?|οικογενειακ.{0,8}δωματι)/i],
 ADULTS_ONLY:[/(?:\bnot\b|\bno\b|without|χωρις|οχι).{0,15}(?:adults?[ -]?only|μονο.{0,8}ενηλικ)/i],
