function isNegatedEvidence(kind:StayConstraintKind,text:string){return evidenceNegation[kind].some(pattern=>pattern.test(text));}
export function stayEvidenceForV16(kind:StayConstraintKind,offer:V8StayOffer){const text=rawText(offer);if(isNegatedEvidence(kind,text))return null;const distance=explicitBeachDistanceMeters(text);switch(kind){case"BEACHFRONT":return /(?:\bbeachfront\b|\bsea[ -]?front\b|\bon the beach\b|\bdirectly on the beach\b|μπροστα.{0,35}(?:θαλασσ|παραλι)|πανω.{0,35}(?:θαλασσ|παραλι)|ακριβως.{0,35}παραλι|παραθαλασσι(?:ο|α|ες))/i.test(text)?"explicit beachfront/seafront wording":null;case"NEAR_BEACH":return distance!=null&&distance<=500?`${distance}m stated beach distance`:/(?:walking distance.{0,30}(?:beach|sea)|near (?:the )?beach|close to (?:the )?beach|διπλα.{0,30}(?:θαλασσ|παραλι)|κοντα.{0,30}παραλι)/i.test(text)?"explicit near-beach wording":null;case"SEA_VIEW":return /(?:sea view|ocean view|θεα.{0,20}θαλασσ|θαλασσ.{0,20}θεα)/i.test(text)?"explicit sea-view wording":null;case"POOL":return /(?:\bpool\b|πισιν)/i.test(text)?"pool stated":null;case"PARKING":return /(?:\bparking\b|παρκιν)/i.test(text)?"parking stated":null;case"EV_CHARGING":return /(?:(?:ev|electric).{0,20}(?:charg|φορτι)|φορτιστ.{0,20}(?:ηλεκτρ|ev))/i.test(text)?"EV charging stated":null;case"BREAKFAST":return /(?:breakfast|πρωιν)/i.test(text)?"breakfast stated":null;case"PET_FRIENDLY":return /(?:pet[ -]?friendly|pet allowed|κατοικιδ)/i.test(text)?"pet-friendly stated":null;case"FAMILY_ROOM":return /(?:family rooms?|οικογενειακ.{0,20}δωματι)/i.test(text)?"family room stated":null;case"ADULTS_ONLY":return /(?:adults?[ -]?only|μονο.{0,15}ενηλικ)/i.test(text)?"adults-only stated":null;}}
export function evaluateStayOfferV16(offer:V8StayOffer,spec:StayConstraintSpec){const evidence=Object.fromEntries([...spec.hard,...spec.soft].map(kind=>[kind,stayEvidenceForV16(kind,offer)])) as Partial<Record<StayConstraintKind,string|null>>,hardFailures=spec.hard.filter(kind=>!evidence[kind]),softMatches=spec.soft.filter(kind=>Boolean(evidence[kind]));return{passed:hardFailures.length===0,hardFailures,evidence,softMatches};}
export function filterStayOffersV16(offers:readonly V8StayOffer[],spec:StayConstraintSpec){return offers.map(offer=>({offer,evaluation:evaluateStayOfferV16(offer,spec)})).filter(row=>row.evaluation.passed);}
