  [`${year}-01-01`,"new-year"],[`${year}-01-06`,"epiphany"],[`${year}-03-25`,"independence-day"],[`${year}-05-01`,"labour-day"],[`${year}-08-15`,"assumption"],[`${year}-10-28`,"oxi-day"],[`${year}-12-25`,"christmas"],[`${year}-12-26`,"boxing-day"],
